async function inspectListingTab(tabId) {
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2500 });

  return await browserjs(tabId, () => {
    const text = document.body ? document.body.innerText : "";
    const name = document.querySelector("h1.propertyName, h1")?.innerText?.trim();
    const address = document.querySelector(".propertyAddressContainer, .propertyAddress")?.innerText?.trim();
    const rentInfo = document.querySelector(".priceBedRangeInfo, .rentInfoContainer")?.innerText?.trim();

    // Check floorplans
    const unitEls = Array.from(document.querySelectorAll(".pricingGridItem, .unitGridContainer, [data-tab-content-id]"));
    const floorplans = unitEls.map(el => {
      const beds = el.querySelector(".detailsTextWrapper, .bedRangeLabel")?.innerText?.trim() || "";
      const rent = el.querySelector(".pricingColumn, .rentLabel")?.innerText?.trim() || "";
      const name = el.querySelector(".modelName, .unitName")?.innerText?.trim() || "";
      return { name, beds, rent };
    }).filter(x => x.beds || x.rent);

    // Look for Stanford University commute in text
    // E.g. "Stanford University\n\tDrive:\t9 min\t3.4 mi"
    let commuteTime = null;
    const stanfordMatch = text.match(/Stanford University\s*(?:\r?\n|\t)+\s*Drive:\s*(\d+\s*min)/i) ||
                          text.match(/Stanford University[^\n\r]*Drive:\s*(\d+\s*min)/i) ||
                          text.match(/Stanford University[^\n\r]*(\d+\s*min)/i);
    if (stanfordMatch) {
      commuteTime = stanfordMatch[1];
    }

    return {
      name,
      address,
      rentInfo,
      floorplans: floorplans.slice(0, 8),
      commuteTime,
      hasText: text.length > 500
    };
  });
}

