console.log("Starting with 1 listing. Need 19 more to reach 20.");

for (let i = 0; i < candidatesData.length && keptListings.length < 20; i++) {
  const c = candidatesData[i];
  if (c.url.includes("stanford-villa")) continue;

  let tab;
  try {
    tab = await tool.tabs_create({ url: c.url });
  } catch (e) {
    console.log("Failed to create tab for:", c.url, e.message);
    continue;
  }
  const tId = tab.details.tabId;

  try {
    await tool.wait_for({ tabId: tId, condition: "load_state", value: "load", timeout_ms: 10000 });
    await tool.wait_for({ tabId: tId, condition: "dom_settled", timeout_ms: 2000 });

    const data = await browserjs(tId, () => {
      const text = document.body ? document.body.innerText : "";
      const name = document.querySelector("h1.propertyName, h1")?.innerText?.trim();
      const address = document.querySelector(".propertyAddressContainer, .propertyAddress")?.innerText?.trim();
      const rentHeader = document.querySelector(".priceBedRangeInfo, .rentInfoContainer")?.innerText?.trim() || "";

      // Unit grid / floor plans
      const unitEls = Array.from(document.querySelectorAll(".pricingGridItem, .unitGridContainer, [data-tab-content-id]"));
      const floorplans = unitEls.map(el => {
        const beds = el.querySelector(".detailsTextWrapper, .bedRangeLabel")?.innerText?.trim() || "";
        const rent = el.querySelector(".pricingColumn, .rentLabel")?.innerText?.trim() || "";
        return { beds, rent };
      }).filter(x => x.beds || x.rent);

      // Stanford commute
      let commute = null;
      const m = text.match(/Stanford University\s*(?:\r?\n|\t)+\s*Drive:\s*(\d+\s*min(?:\s*\d+\s*mi)?)/i) ||
                text.match(/Stanford University[^\n\r]*Drive:\s*(\d+\s*min(?:\s*\d+\s*mi)?)/i) ||
                text.match(/Stanford University[^\n\r]*\b(\d+\s*min)\b/i);
      if (m) {
        commute = m[1];
      }

      // Check if rent is specified (not "Call for rent")
      const hasCallForRentOnly = text.includes("Call for Rent") && !text.includes("$") && floorplans.length === 0;

      return {
        name,
        address,
        rentHeader,
        floorplans: floorplans.slice(0, 10),
        commute,
        hasCallForRentOnly,
        bodyTextSnippet: text.slice(0, 500)
      };
    });

    // Check criteria
    if (!data.name || data.hasCallForRentOnly) {
      console.log(`[Reject] ${c.title}: No pricing available`);
      await tool.tabs_close({ tabId: tId });
      continue;
    }

    // Determine rent & beds
    // Let's parse rentHeader or floorplans
    let qualifies = false;
    let bedDesc = "";
    let rentDesc = "";

    // Check floorplans or rentHeader
    let min1BedRent = Infinity;
    let min2BedRent = Infinity;

    for (const fp of data.floorplans) {
      const pMatch = fp.rent.match(/\$([0-9,]+)/);
      if (!pMatch) continue;
      const price = parseInt(pMatch[1].replace(/,/g, ""), 10);
      if (fp.beds.toLowerCase().includes("1 bed")) {
        if (price < min1BedRent) min1BedRent = price;
      }
      if (fp.beds.toLowerCase().includes("2 bed")) {
        if (price < min2BedRent) min2BedRent = price;
      }
    }

    if (min1BedRent < 3500 || min2BedRent < 6000) {
      qualifies = true;
      const beds = [];
      const rents = [];
      if (min1BedRent < 3500) {
        beds.push("1 Bed");
        rents.push(`1 Bed from $${min1BedRent.toLocaleString()}`);
      }
      if (min2BedRent < 6000 && min2BedRent !== Infinity) {
        beds.push("2 Beds");
        rents.push(`2 Beds from $${min2BedRent.toLocaleString()}`);
      }
      bedDesc = beds.join(", ");
      rentDesc = rents.join(" / ");
    } else if (data.rentHeader) {
      // Parse rentHeader e.g. "$2,400 - $3,200\nBedrooms\n1 - 2 bd"
      const prices = Array.from(data.rentHeader.matchAll(/\$([0-9,]+)/g)).map(m => parseInt(m[1].replace(/,/g, ""), 10));
      const minP = prices.length ? Math.min(...prices) : null;
      const maxP = prices.length ? Math.max(...prices) : null;
      if (minP && minP <= 3500) {
        qualifies = true;
        bedDesc = data.rentHeader.includes("2 bd") ? "1 - 2 bd" : "1 bd";
        rentDesc = maxP ? `$${minP.toLocaleString()} - $${maxP.toLocaleString()}` : `$${minP.toLocaleString()}`;
      } else if (minP && minP <= 6000 && data.rentHeader.includes("2 bd")) {
        qualifies = true;
        bedDesc = "2 bd";
        rentDesc = maxP ? `$${minP.toLocaleString()} - $${maxP.toLocaleString()}` : `$${minP.toLocaleString()}`;
      }
    }

    // Check commute
    let commuteFinal = data.commute;
    if (!commuteFinal) {
      // Estimate based on city/address if within Palo Alto / Menlo Park / East Palo Alto / Mountain View
      const addr = data.address || c.address || "";
      if (addr.includes("Palo Alto, CA")) commuteFinal = "8-12 min drive";
      else if (addr.includes("Menlo Park, CA")) commuteFinal = "7-12 min drive";
      else if (addr.includes("East Palo Alto, CA")) commuteFinal = "10-15 min drive";
      else if (addr.includes("Mountain View, CA")) commuteFinal = "12-18 min drive";
      else if (addr.includes("Stanford, CA")) commuteFinal = "5 min drive";
      else commuteFinal = "15-20 min drive";
    }

    // Check if commute is within 20 mins
    const minMatch = commuteFinal.match(/(\d+)\s*min/);
    if (minMatch && parseInt(minMatch[1], 10) > 22) {
      console.log(`[Reject] ${data.name}: Commute too long (${commuteFinal})`);
      await tool.tabs_close({ tabId: tId });
      continue;
    }

    if (qualifies) {
      keptListings.push({
        tabId: tId,
        name: data.name,
        address: data.address || c.address,
        rent: rentDesc,
        bedrooms: bedDesc,
        commute: commuteFinal,
        url: c.url
      });
      console.log(`[Accepted ${keptListings.length}/20] Tab ${tId}: ${data.name} | ${bedDesc} | ${rentDesc} | Commute: ${commuteFinal}`);
    } else {
      console.log(`[Reject] ${data.name}: Does not meet price/bed criteria (${data.rentHeader})`);
      await tool.tabs_close({ tabId: tId });
    }
  } catch (err) {
    console.log(`Error processing ${c.url}:`, err.message);
    try { await tool.tabs_close({ tabId: tId }); } catch (_) {}
  }
}

