const tabId = 787783793;

async function getListingsFromUrl(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    // Collect all listing links and metadata from search page
    const cards = Array.from(document.querySelectorAll("li.mortar-wrapper, article.placard"));
    return cards.map(c => {
      const link = c.querySelector("a.property-link, a.property-information");
      const title = c.querySelector(".property-title, .title")?.textContent?.trim();
      const address = c.querySelector(".property-address, .address")?.textContent?.trim();
      const price = c.querySelector(".property-pricing, .price-range, .rent")?.textContent?.trim();
      const beds = c.querySelector(".property-beds, .bed-range, .beds")?.textContent?.trim();
      return {
        url: link?.href,
        title,
        address,
        price,
        beds
      };
    }).filter(x => x.url && !x.url.includes("apartments.com/apartments/"));
  });
}

