const tabId = 787783793;

const searchUrls = [
  "https://www.apartments.com/palo-alto-ca/1-bedrooms-under-3500/",
  "https://www.apartments.com/palo-alto-ca/2-bedrooms-under-6000/",
  "https://www.apartments.com/menlo-park-ca/1-bedrooms-under-3500/",
  "https://www.apartments.com/menlo-park-ca/2-bedrooms-under-6000/",
  "https://www.apartments.com/mountain-view-ca/1-bedrooms-under-3500/"
];

const candidates = [];
const seenUrls = new Set();
// Stanford Villa is already in tab 787784175
seenUrls.add("https://www.apartments.com/stanford-villa-palo-alto-ca/5ezwzbq/");

for (const sUrl of searchUrls) {
  await tool.navigate({ tabId, url: sUrl });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  const items = await browserjs(tabId, () => {
    const placards = Array.from(document.querySelectorAll("li.mortar-wrapper, article.placard"));
    return placards.map(p => {
      const link = p.querySelector("a.property-link, a.property-information");
      const title = p.querySelector(".property-title, .title")?.textContent?.trim();
      const address = p.querySelector(".property-address, .address")?.textContent?.trim();
      const price = p.querySelector(".property-pricing, .price-range, .rent")?.textContent?.trim();
      const beds = p.querySelector(".property-beds, .bed-range, .beds")?.textContent?.trim();
      const url = link?.href;
      return { url, title, address, price, beds };
    }).filter(x => x.url && !x.url.includes("/apartments/"));
  });

  for (const item of items) {
    // Clean URL (remove hash / query params)
    const cleanUrl = item.url.split("?")[0].split("#")[0];
    if (!seenUrls.has(cleanUrl)) {
      seenUrls.add(cleanUrl);
      candidates.push({ ...item, url: cleanUrl });
    }
  }
}

console.log("Total unique candidate listings collected:", candidates.length);
console.log("First 10 candidates:", candidates.slice(0, 10));
await write("tmp://candidates.json", JSON.stringify(candidates, null, 2), "application/json");

