    url: "https://www.apartments.com/stanford-villa-palo-alto-ca/5ezwzbq/"
  }
];

console.log("Starting with 1 listing. Need 19 more to reach 20.");

for (let i = 0; i < candidatesData.length && keptListings.length < 20; i++) {
  const c = candidatesData[i];
  if (c.url.includes("stanford-villa")) continue;

  let tab;
  try {
    tab = await tool.tabs_create({ url: c.url });
