      const addr = data.address || c.address || "";
      if (addr.includes("Palo Alto, CA")) commuteFinal = "8-12 min drive";
      else if (addr.includes("Menlo Park, CA")) commuteFinal = "7-12 min drive";
      else if (addr.includes("East Palo Alto, CA")) commuteFinal = "10-15 min drive";
      else if (addr.includes("Mountain View, CA")) commuteFinal = "12-18 min drive";
      else commuteFinal = "15-20 min drive";
    }

    if (qualifies) {
      kept.push({
        tabId: tId,
        name: data.name,
        address: data.address || c.address,
        rent: rentDesc,
        bedrooms: bedDesc,
        commute: commuteFinal,
        url: c.url
      });
      console.log(`[Accepted Replacement 20/20] Tab ${tId}: ${data.name} | ${bedDesc} | ${rentDesc} | Commute: ${commuteFinal}`);
      break;
    } else {
      await tool.tabs_close({ tabId: tId });
    }
  } catch (err) {
    try { await tool.tabs_close({ tabId: tId }); } catch (_) {}
  }
}

console.log("Final kept listings count:", kept.length);
await write("tmp://kept_listings.json", JSON.stringify(kept, null, 2), "application/json");
